hotel_name = #{hotelName}, platform = #{platform}, city = #{city}, room_type = #{roomType}, check_in_date = #{checkInDate}, check_out_date = #{checkOutDate}, target_price = #{targetPrice}, current_price = #{currentPrice}, currency = #{currency}, channel_url = #{channelUrl}, crawl_enabled = #{crawlEnabled}, crawl_strategy = #{crawlStrategy}, crawl_config = #{crawlConfig}, status = #{status}, latest_change = #{latestChange}, last_checked_time = #{lastCheckedTime}, last_crawled_at = #{lastCrawledAt}, last_error_message = #{lastErrorMessage}, notify_enabled = #{notifyEnabled}, remark = #{remark}, update_by = #{updateBy}, update_time = #{updateTime}
